"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");

const UA =
  "Mozilla/5.0 (Linux; Android 13; SM-S918B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.6422.64 Mobile Safari/537.36";

const PAGE_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "en-US,en;q=0.9",
  "accept-encoding": "gzip, deflate, br",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?1",
  "sec-ch-ua-platform": '"Android"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u
    ? String(u).replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&")
    : null;

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorbLines(lines) {
    if (!Array.isArray(lines)) return;
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  absorb(headers) {
    this.absorbLines(headers["set-cookie"]);
  }
  absorbFetch(headers) {
    const lines =
      typeof headers.getSetCookie === "function" ? headers.getSetCookie() : [];
    this.absorbLines(lines);
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function decodeBody(buffer, encoding) {
  return new Promise((resolve, reject) => {
    const enc = String(encoding || "").toLowerCase();
    if (enc === "gzip" || enc === "x-gzip") {
      zlib.gunzip(buffer, (err, out) => (err ? reject(err) : resolve(out.toString("utf8"))));
    } else if (enc === "deflate") {
      zlib.inflate(buffer, (err, out) => (err ? reject(err) : resolve(out.toString("utf8"))));
    } else if (enc === "br") {
      zlib.brotliDecompress(buffer, (err, out) =>
        err ? reject(err) : resolve(out.toString("utf8"))
      );
    } else {
      resolve(buffer.toString("utf8"));
    }
  });
}

function fetchOnce(current, jar) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(current);
    } catch {
      reject(new Error("Invalid Likee URL: " + current));
      return;
    }
    const lib = target.protocol === "http:" ? http : https;
    const headers = { ...PAGE_HEADERS };
    const cookie = jar.toString();
    if (cookie) headers.cookie = cookie;
    const req = lib.get(
      {
        hostname: target.hostname,
        port: target.port || undefined,
        path: target.pathname + target.search,
        headers,
      },
      (res) => {
        jar.absorb(res.headers);
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", async () => {
          try {
            const body = await decodeBody(
              Buffer.concat(chunks),
              res.headers["content-encoding"]
            );
            resolve({
              status: res.statusCode || 0,
              location: res.headers.location || null,
              body,
            });
          } catch (err) {
            reject(err);
          }
        });
        res.on("error", reject);
      }
    );
    req.setTimeout(20000, () => {
      req.destroy(new Error("Likee request timed out"));
    });
    req.on("error", reject);
  });
}

async function fetchOnceFetch(current, jar) {
  const ctl = new AbortController();
  const to = setTimeout(() => ctl.abort(), 20000);
  let res;
  try {
    const headers = { ...PAGE_HEADERS };
    delete headers["accept-encoding"];
    const cookie = jar.toString();
    if (cookie) headers.cookie = cookie;
    res = await fetch(current, {
      headers,
      redirect: "manual",
      signal: ctl.signal,
    });
  } finally {
    clearTimeout(to);
  }
  jar.absorbFetch(res.headers);
  const location = res.headers.get("location");
  const body = await res.text().catch(() => "");
  return { status: res.status, location, body };
}

async function fetchStep(current, jar) {
  if (typeof fetch === "function") return fetchOnceFetch(current, jar);
  return fetchOnce(current, jar);
}

async function fetchChain(startUrl, jar) {
  let current = startUrl;
  for (let hop = 0; hop < 6; hop++) {
    const res = await fetchStep(current, jar);
    if (res.status >= 300 && res.status < 400 && res.location) {
      const next = new URL(res.location, current);
      if (!/^https?:$/.test(next.protocol) || /(^|\.)onelink\.me$/.test(next.hostname)) {
        throw new Error(
          "Likee redirected this post to the app instead of serving a web page - it cannot be read logged-out"
        );
      }
      current = next.href;
      continue;
    }
    return { html: res.body, finalUrl: current, status: res.status };
  }
  throw new Error("Too many redirects while resolving this Likee link");
}

function isHomepage(finalUrl) {
  try {
    const u = new URL(finalUrl);
    return u.pathname === "/" || u.pathname === "";
  } catch {
    return false;
  }
}

async function fetchSharePage(startUrl, jar, hasData, attempts = 3) {
  let lastError = null;
  let lastHtml = "";
  for (let i = 0; i < attempts; i++) {
    try {
      const { html, finalUrl } = await fetchChain(startUrl, jar);
      lastHtml = html;
      if (hasData(html)) return { html, finalUrl };
      if (isHomepage(finalUrl)) {
        lastError = new Error(
          "Likee redirected this link to its homepage - the post may be deleted or region-restricted"
        );
      } else {
        lastError = new Error("Likee served a page without post data");
      }
    } catch (err) {
      lastError = err;
      if (/redirected this post to the app/.test(err.message)) throw err;
    }
    await new Promise((r) => setTimeout(r, 700));
  }
  if (lastHtml && hasData(lastHtml)) return { html: lastHtml, finalUrl: startUrl };
  throw lastError || new Error("Could not fetch this Likee page");
}

function extractWindowData(html) {
  const marker = html.indexOf("window.data");
  if (marker < 0) return null;
  const open = html.indexOf("{", marker);
  if (open < 0) return null;
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = open; i < html.length; i++) {
    const c = html[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (c === "\\") escaped = true;
      else if (c === '"') inString = false;
      continue;
    }
    if (c === '"') inString = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        try {
          return JSON.parse(html.slice(open, i + 1));
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function extractOg(html) {
  const og = {};
  const re = /<meta[^>]+property="(og:[^"]+)"[^>]+content="([^"]*)"/g;
  let m;
  while ((m = re.exec(html))) {
    if (og[m[1]] === undefined) og[m[1]] = m[2];
  }
  const reReverse = /<meta[^>]+content="([^"]*)"[^>]+property="(og:[^"]+)"/g;
  while ((m = reReverse.exec(html))) {
    if (og[m[2]] === undefined) og[m[2]] = m[1];
  }
  return og;
}

function num(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = parseInt(String(v).replace(/,/g, ""), 10);
  return Number.isFinite(n) ? n : null;
}

function shapeVideo(d, og, code, pageUrl) {
  const originUrl =
    typeof d.origin_video_url === "string" && d.origin_video_url
      ? d.origin_video_url
      : null;
  const plainUrl =
    typeof d.video_url === "string" && d.video_url ? d.video_url : og["og:video"] || null;
  const waterUrl =
    typeof d.video_water_url === "string" && d.video_water_url ? d.video_water_url : null;
  const video = originUrl || plainUrl;
  const username = d.likeeId || d.like_id || null;
  return {
    caption: d.msg_text || d.msgText || "",
    author: {
      username,
      fullName: d.nick_name || d.nickname || null,
    },
    media: {
      image: d.image1 || d.coverUrl || d.cover_url || og["og:image"] || null,
      video,
    },
    download: {
      video,
      videoWatermarked: waterUrl && waterUrl !== video ? waterUrl : null,
      image: d.image1 || d.coverUrl || d.cover_url || og["og:image"] || null,
    },
    url: pageUrl,
  };
}

function shapeFromOg(og, code, pageUrl) {
  return {
    caption: "",
    author: { username: null, fullName: null },
    media: {
      image: og["og:image"] || null,
      video: og["og:video"] || null,
    },
    download: {
      video: og["og:video"] || null,
      videoWatermarked: null,
      image: og["og:image"] || null,
    },
    url: pageUrl,
  };
}

function parseVideoInput(input) {
  const s = String(input || "").trim();
  let m = s.match(/(?:l\.)?likee\.video\/v\/([A-Za-z0-9_-]{3,20})/);
  if (m) return { code: m[1] };
  m = s.match(/likee\.video\/@([^/?#]+)\/video\/(\d{6,25})/);
  if (m) return { longId: m[2], username: m[1] };
  if (/^[A-Za-z0-9_-]{3,20}$/.test(s)) return { code: s };
  return null;
}

async function scrapeVideo(input) {
  const parsed = parseVideoInput(input);
  if (!parsed) throw new Error("Invalid Likee video URL or share code");
  if (parsed.longId) {
    throw new Error(
      "Likee does not serve long /@user/video/<id> URLs to logged-out web requests (it redirects them to the homepage). Use the post's short share link instead: l.likee.video/v/<code>"
    );
  }
  const code = parsed.code;
  const jar = new Jar();
  const startUrl = `https://likee.video/v/${code}`;
  const { html, finalUrl } = await fetchSharePage(
    startUrl,
    jar,
    (h) => !!extractWindowData(h) || /property="og:video"/.test(h)
  );
  const og = extractOg(html);
  const d = extractWindowData(html);
  let data;
  if (d && (d.post_id || d.video_url)) {
    data = shapeVideo(d, og, code, finalUrl);
  } else if (og["og:video"]) {
    data = shapeFromOg(og, code, finalUrl);
  } else {
    throw new Error(
      "Could not extract this post - it may be deleted, or Likee changed its share page format"
    );
  }
  return { data, og };
}

module.exports = async function fetchSelf(url) {
  try {
    const { data, og } = await scrapeVideo(url);

    const video = cleanUrl(data.download.video || data.media.video || null);
    if (!video) {
      throw new Error(
        "Likee video not found - the share page returned post info but no media URL (the media may have been deleted)"
      );
    }

    const title = data.caption || og["og:title"] || null;
    const uploader = data.author.fullName || data.author.username || null;
    const thumbnail = data.download.image || data.media.image || null;

    return {
      success: true,
      source: "Likee",
      data: {
        title: title || null,
        uploader,
        thumbnail: thumbnail ? cleanUrl(thumbnail) : null,
        download: { video },
      },
    };
  } catch (e) {
    if (/^Likee Error:/.test(e.message)) throw e;
    throw new Error("Likee Error: " + e.message);
  }
};
